// Toolsets whose latest version references a proxy tool, or the per-tool
// (direct) tools, of an external MCP attachment on any deployment, across
// every organization, with what staff need to decide whether each one switches
// in place or is deleted. A toolset is live when it is MCP-enabled or fronted
// by a live mcp_servers row; on_active_deployment is set when its project's
// active deployment still serves the attachment. Pass toolset_ids to narrow
// the scan.
// Every toolset, live or not, so the ones left with nothing to migrate are
// listed for deletion.
// Definitions on any deployment; on_active marks the ones the project's active
// deployment serves, which are all the migration looks at.
func (q *Queries) ListCandidates(ctx context.Context, toolsetIds []uuid.UUID) ([]ListCandidatesRow, error) {
	rows, err := q.db.Query(ctx, listCandidates, toolsetIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListCandidatesRow
	for rows.Next() {
		var i ListCandidatesRow
		if err := rows.Scan(
			&i.ToolsetID,
			&i.OrganizationID,
			&i.OrganizationName,
			&i.OrganizationSlug,
			&i.HasOrganizationMetadata,
			&i.ProjectID,
			&i.ProjectName,
			&i.ProjectSlug,
			&i.ToolsetName,
			&i.ToolsetSlug,
			&i.McpSlug,
			&i.CustomDomainID,
			&i.UserSessionIssuerID,
			&i.ExternalOauthServerID,
			&i.OauthProxyServerID,
			&i.ToolsetHasVariations,
			&i.UserSessionIssuerSlug,
			&i.Live,
			&i.MigratedInPlace,
			&i.OnActiveDeployment,
			&i.AttachmentCount,
			&i.RemoteUrls,
			&i.TransportTypes,
			&i.DeclaresHeaders,
			&i.RequiresOauth,
			&i.ServesOtherTools,
			&i.ServerCount,
			&i.ServerUserSessionIssuerID,
			&i.ServerHasVariations,
			&i.EndpointCount,
			&i.McpSlugIsEndpoint,
			&i.HasPrompts,
			&i.HasSlackApps,
			&i.HasUserOauthTokens,
			&i.InGateway,
			&i.RemoteSessionIssuerIds,
			&i.RemoteIssuerNames,
			&i.HasSelfOwnedClients,
			&i.HasEmaBindings,
			&i.OtherToolsetsOnIssuer,
			&i.SessionResources,
			&i.OtherNonRemoteServersOnIssuer,
			&i.OtherRemoteUrlsOnIssuer,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

